626	// ---------------------------------------------------------------------------
627	// Strict JSON parser used by `verify`.
628	//
629	// Written by hand so the crate keeps zero third-party runtime dependencies.
630	// Unlike a tolerant parser it enforces every rule the verify contract relies
631	// on: exactly one complete value surrounded only by JSON whitespace, no
632	// duplicate member names within an object, strict number grammar (integers
633	// only, no fractions/exponents/leading zeros), strings decoded per RFC 8259
634	// including surrogate pairs. Anything it cannot parse is a corrupt record
635	// (exit 2), never a mismatch.
636	// ---------------------------------------------------------------------------
637	
638	mod json {
639	    #[derive(Debug, PartialEq)]
640	    pub enum JsonValue {
641	        /// Parsed as an integer because the record grammar has no fractional
642	        /// values; the width comfortably covers u32 and common JSON integers.
643	        Number(i128),
644	        String(String),
645	        Array(Vec<JsonValue>),
646	        /// Members kept in source order; names are unique (parser-enforced).
647	        Object(Vec<(String, JsonValue)>),
648	        // Accepted so documents using them parse, but records containing them
649	        // are rejected structurally by the caller.
650	        Bool(bool),
651	        Null,
652	    }
653	
654	    struct Parser<'a> {
655	        bytes: &'a [u8],
656	        pos: usize,
657	        /// Current object/array nesting depth, capped so adversarial input
658	        /// ("[[[[...")") cannot exhaust the stack and crash the verifier.
659	        depth: usize,
660	    }
661	
662	    /// Far above the depth a real record ever reaches (record → `fields`
663	    /// array → string is depth 2) while staying well within stack limits.
664	    const MAX_DEPTH: usize = 64;
665	
666	    /// Parse exactly one JSON value: optional leading/trailing JSON whitespace
667	    /// is allowed, but any trailing non-whitespace content (including a second
668	    /// object) is an error.
669	    pub fn parse_single(input: &str) -> Result<JsonValue, String> {
670	        let mut p = Parser {
671	            bytes: input.as_bytes(),
672	            pos: 0,
673	            depth: 0,
674	        };
675	        p.skip_ws();
676	        if p.pos == p.bytes.len() {
677	            return Err("input is empty; expected one JSON record".to_string());
678	        }
679	        let value = p.parse_value()?;
680	        p.skip_ws();
681	        if p.pos != p.bytes.len() {
682	            return Err(
683	                "trailing non-whitespace content after record; exactly one JSON object is allowed"
684	                    .to_string(),
685	            );
686	        }
687	        Ok(value)
688	    }
689	
690	    impl<'a> Parser<'a> {
691	        fn skip_ws(&mut self) {
692	            while self.pos < self.bytes.len()
693	                && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r')
694	            {
695	                self.pos += 1;
696	            }
697	        }
698	
699	        fn peek(&self) -> Option<u8> {
700	            self.bytes.get(self.pos).copied()
701	        }
702	
703	        fn enter_container(&mut self) -> Result<(), String> {
704	            if self.depth >= MAX_DEPTH {
705	                return Err("JSON nesting is too deep".to_string());
706	            }
707	            self.depth += 1;
708	            Ok(())
709	        }
710	
711	        fn parse_value(&mut self) -> Result<JsonValue, String> {
712	            self.skip_ws();
713	            match self.peek() {
714	                Some(b'{') => self.parse_object(),
715	                Some(b'[') => self.parse_array(),
716	                Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
717	                Some(b't') => self.parse_lit("true", JsonValue::Bool(true)),
718	                Some(b'f') => self.parse_lit("false", JsonValue::Bool(false)),
719	                Some(b'n') => self.parse_lit("null", JsonValue::Null),
720	                Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
721	                Some(_) => Err("unexpected character while parsing JSON".to_string()),
722	                None => Err("unexpected end of JSON input".to_string()),
723	            }
724	        }
725	
726	        fn parse_lit(&mut self, lit: &str, value: JsonValue) -> Result<JsonValue, String> {
727	            if self.bytes[self.pos..].starts_with(lit.as_bytes()) {
728	                self.pos += lit.len();
729	                Ok(value)
730	            } else {
731	                Err("malformed JSON literal".to_string())
732	            }
733	        }
734	
735	        fn parse_object(&mut self) -> Result<JsonValue, String> {
736	            self.enter_container()?;
737	            let result = self.parse_object_inner();
738	            self.depth -= 1;
739	            result
740	        }
741	
742	        fn parse_object_inner(&mut self) -> Result<JsonValue, String> {
743	            self.pos += 1; // '{'
744	            let mut entries: Vec<(String, JsonValue)> = Vec::new();
745	            self.skip_ws();
746	            if self.peek() == Some(b'}') {
747	                self.pos += 1;
748	                return Ok(JsonValue::Object(entries));
749	            }
750	            loop {
751	                self.skip_ws();
752	                if self.peek() != Some(b'"') {
753	                    return Err("expected a string member name in JSON object".to_string());
754	                }
755	                let name = self.parse_string()?;
756	                self.skip_ws();
757	                if self.peek() != Some(b':') {
758	                    return Err("expected ':' after JSON member name".to_string());
759	                }
760	                self.pos += 1;
761	                let value = self.parse_value()?;
762	                if entries.iter().any(|(n, _)| *n == name) {
763	                    return Err("JSON object contains a duplicate member".to_string());
764	                }
765	                entries.push((name, value));
766	                self.skip_ws();
767	                match self.peek() {
768	                    Some(b',') => {
769	                        self.pos += 1;
770	                    }
771	                    Some(b'}') => {
772	                        self.pos += 1;
773	                        break;
774	                    }
775	                    Some(_) => return Err("expected ',' or '}}' in JSON object".to_string()),
776	                    None => return Err("unterminated JSON object".to_string()),
777	                }
778	            }
779	            Ok(JsonValue::Object(entries))
780	        }
781	
782	        fn parse_array(&mut self) -> Result<JsonValue, String> {
783	            self.enter_container()?;
784	            let result = self.parse_array_inner();
785	            self.depth -= 1;
786	            result
787	        }
788	
789	        fn parse_array_inner(&mut self) -> Result<JsonValue, String> {
790	            self.pos += 1; // '['
791	            let mut items = Vec::new();
792	            self.skip_ws();
793	            if self.peek() == Some(b']') {
794	                self.pos += 1;
795	                return Ok(JsonValue::Array(items));
796	            }
797	            loop {
798	                items.push(self.parse_value()?);
799	                self.skip_ws();
800	                match self.peek() {
801	                    Some(b',') => {
802	                        self.pos += 1;
803	                        self.skip_ws();
804	                    }
805	                    Some(b']') => {
806	                        self.pos += 1;
807	                        break;
808	                    }
809	                    Some(_) => return Err("expected ',' or ']' in JSON array".to_string()),
810	                    None => return Err("unterminated JSON array".to_string()),
811	                }
812	            }
813	            Ok(JsonValue::Array(items))
814	        }
815	
816	        fn parse_string(&mut self) -> Result<String, String> {
817	            self.pos += 1; // opening quote
818	            let mut out = String::new();
819	            loop {
820	                match self.peek() {
821	                    None => return Err("unterminated JSON string".to_string()),
822	                    Some(b'"') => {
823	                        self.pos += 1;
824	                        break;
825	                    }
826	                    Some(b'\\') => {
827	                        self.pos += 1;
828	                        let esc = self
829	                            .peek()
830	                            .ok_or("unterminated JSON escape sequence")?;
831	                        self.pos += 1;
832	                        match esc {
833	                            b'"' => out.push('"'),
834	                            b'\\' => out.push('\\'),
835	                            b'/' => out.push('/'),
836	                            b'b' => out.push('\u{0008}'),
837	                            b'f' => out.push('\u{000c}'),
838	                            b'n' => out.push('\n'),
839	                            b'r' => out.push('\r'),
840	                            b't' => out.push('\t'),
841	                            b'u' => {
842	                                let hi = self.parse_hex4()?;
843	                                let c = if (0xD800..=0xDBFF).contains(&hi) {
844	                                    // High surrogate must be followed by "\uXXXX"
845	                                    // low surrogate; lone surrogates are invalid.
846	                                    if self.peek() != Some(b'\\') {
847	                                        return Err(
848	                                            "lone UTF-16 high surrogate in JSON string".to_string()
849	                                        );
850	                                    }
851	                                    self.pos += 1;
852	                                    if self.peek() != Some(b'u') {
853	                                        return Err(
854	                                            "bad surrogate pair escape in JSON string".to_string()
855	                                        );
856	                                    }
857	                                    self.pos += 1;
858	                                    let lo = self.parse_hex4()?;
859	                                    if !(0xDC00..=0xDFFF).contains(&lo) {
860	                                        return Err(
861	                                            "low surrogate out of range in JSON string".to_string()
862	                                        );
863	                                    }
864	                                    char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
865	                                        .ok_or("invalid surrogate pair in JSON string")?
866	                                } else if (0xDC00..=0xDFFF).contains(&hi) {
867	                                    return Err(
868	                                        "lone UTF-16 low surrogate in JSON string".to_string()
869	                                    );
870	                                } else {
871	                                    char::from_u32(hi)
872	                                        .ok_or("invalid unicode escape in JSON string")?
873	                                };
874	                                out.push(c);
875	                            }
876	                            _ => {
877	                                return Err("invalid escape sequence in JSON string".to_string())
878	                            }
879	                        }
880	                    }
881	                    Some(c) if c < 0x20 => {
882	                        return Err("unescaped control character in JSON string".to_string())
883	                    }
884	                    Some(_) => {
885	                        // Copy one whole UTF-8 scalar at a time, validating that
886	                        // the raw bytes really are UTF-8 (the surrounding input
887	                        // is &str so this cannot fail, but keep the boundary
888	                        // explicit rather than slicing mid-char).
889	                        let start = self.pos;
890	                        self.pos += 1;
891	                        while self.pos < self.bytes.len() {
892	                            let b = self.bytes[self.pos];
893	                            if b == b'"' || b == b'\\' || b < 0x20 {
894	                                break;
895	                            }
896	                            self.pos += 1;
897	                        }
898	                        let chunk = std::str::from_utf8(&self.bytes[start..self.pos])
899	                            .map_err(|_| "invalid UTF-8 inside JSON string".to_string())?;
900	                        out.push_str(chunk);
901	                    }
902	                }
903	            }
904	            Ok(out)
905	        }
906	
907	        fn parse_hex4(&mut self) -> Result<u32, String> {
908	            let mut v = 0u32;
909	            for _ in 0..4 {
910	                if self.peek().is_none() {
911	                    return Err("truncated \\u escape in JSON string".to_string());
912	                }
913	                let c = self.peek().unwrap();
914	                if !(c as char).is_ascii_hexdigit() {
915	                    return Err("bad hexadecimal digit in \\u escape".to_string());
916	                }
917	                let d = (c as char).to_digit(16).unwrap();
918	                self.pos += 1;
919	                v = v * 16 + d;
920	            }
921	            Ok(v)
922	        }
923	
924	        /// Strict RFC 8259 integer grammar. The record format has no fractional
925	        /// values, so `.`/`e` forms are rejected rather than truncated.
926	        fn parse_number(&mut self) -> Result<JsonValue, String> {
927	            let start = self.pos;
928	            if self.peek() == Some(b'-') {
929	                self.pos += 1;
930	            }
931	            match self.peek() {
932	                Some(b'0') => {
933	                    self.pos += 1;
934	                    // A leading zero must not be followed by more digits.
935	                    if matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
936	                        return Err("numbers with leading zeros are not valid JSON".to_string());
937	                    }
938	                }
939	                Some(c) if c.is_ascii_digit() => {
940	                    while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
941	                        self.pos += 1;
942	                    }
943	                }
944	                _ => return Err("malformed JSON number".to_string()),
945	            }
946	            // No fraction or exponent: this grammar only carries integers.
947	            if matches!(self.peek(), Some(b'.' | b'e' | b'E')) {
948	                return Err(
949	                    "record numbers must be integers; fractions and exponents are not accepted"
950	                        .to_string(),
951	                );
952	            }
953	            let text = std::str::from_utf8(&self.bytes[start..self.pos])
954	                .map_err(|_| "invalid UTF-8 in JSON number".to_string())?;
955	            text.parse::<i128>()
956	                .map(JsonValue::Number)
957	                .map_err(|_| "JSON integer is out of supported range".to_string())
958	        }
959	    }
960	}
