1041	    /// Build a format-1 record JSON string for the given content, with the
1042	    /// correct tag for `key`.
1043	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
1044	        let tag = sign_tag(key_hex, key_id, version, fields);
1045	        let fields_json = fields
1046	            .iter()
1047	            .map(|f| format!("\"{}\"", json_escape(f)))
1048	            .collect::<Vec<_>>()
1049	            .join(",");
1050	        format!(
1051	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
1052	            json_escape(key_id),
1053	            version,
1054	            fields_json,
1055	            tag
1056	        )
1057	    }
