1093	        ));
1094	        // Uppercase tag spelling still represents the same 32 bytes.
1095	        let real_tag = sign_tag(key, "id", 1, &["x"]);
1096	        let upper = record_for(key, "id", 1, &["x"]).replace(&real_tag, &real_tag.to_uppercase());
1097	        assert!(matches!(
1098	            verify_input(upper.as_bytes(), key),
1099	            VerifyOutcome::Valid
1100	        ));
1101	    }
